import { router, type Href } from 'expo-router';

/** Close the whole log modal flow and land on Home. */
export function finishLogFlow() {
  try {
    router.dismissTo('/');
  } catch {
    router.replace('/');
  }
}

/** Close the flow without saving (pops the modal). */
export function cancelLogFlow() {
  if (router.canGoBack()) router.back();
  else router.replace('/');
}

// Typed-routes are generated by the dev server; cast so these compile before/without regeneration.
const href = (h: unknown) => h as unknown as Href;

export const goReview = (mealId?: string) =>
  router.push(href(mealId ? { pathname: '/log/review', params: { mealId } } : '/log/review'));
export const goCapture = () => router.push(href('/log/capture'));
export const goAddFood = () => router.push(href('/log/add-food'));
/** from='start': first screen of the flow (adding goes to review). from='review': pushed on top of review. */
export const goSearch = (from: 'start' | 'review') =>
  router.push(href({ pathname: '/log/search', params: { from } }));
/** Replace the current screen with review (used after the first item is added from search). */
export const replaceWithReview = () => router.replace(href('/log/review'));
